package vip.xiaonuo.srm.quality;
import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.context.event.EventListener;import org.springframework.web.multipart.MultipartFile;import org.springframework.transaction.support.*;import vip.xiaonuo.flow.api.*;import vip.xiaonuo.srm.api.SrmSupplierAccessApi.Context;import static vip.xiaonuo.srm.quality.QualityStore.*;import static vip.xiaonuo.srm.quality.QualityInputs.*;
@Service @RequiredArgsConstructor @Transactional(isolation=Isolation.READ_COMMITTED) public class QualityCases {
 final QualityStore x;final SrmFlowApi flow;
 public Map<String,Object> create(Context a,String kind,Object input){if(kind.equals("PPAP"))x.supplierWriter(a);else x.sqe(a);Draft draft=input instanceof Draft d?d:null;Scar scar=input instanceof Scar d?d:null;String sid=draft!=null?draft.supplierId():scar.supplierId(),key=draft!=null?draft.requestKey():scar.requestKey(),title=draft!=null?draft.title():scar.title();var supplier=x.access.requireSupplier(a,sid,true);var old=x.db.queryForList("SELECT ID,REQUEST_HASH FROM SRM_QL_CASE WHERE ORG_ID=? AND KIND=? AND REQUEST_KEY=?",supplier.orgId(),kind,key);if(!old.isEmpty()){require(s(old.get(0),"REQUEST_HASH").equals(x.hash(input)),409,"请求号内容冲突");return detail(a,s(old.get(0),"ID"));}var meta=new LinkedHashMap<String,Object>();meta.put("policy",x.policy(supplier.orgId()));if(scar!=null)meta.put("description",scar.description());long due=System.currentTimeMillis()+((Number)((Map<?,?>)meta.get("policy")).get("responseDays")).longValue()*86400000;String id=id();x.db.update("INSERT INTO SRM_QL_CASE(ID,ORG_ID,SUPPLIER_ID,KIND,TITLE,STATUS,META_CIPHER,DEFECT_KEY,SEVERITY,DUE_MS,CREATED_BY,REQUEST_KEY,REQUEST_HASH,CREATED_AT,UPDATED_AT) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(3),NOW(3))",id,supplier.orgId(),sid,kind,title,kind.equals("PPAP")?"DRAFT":"OPEN",x.crypto.encrypt(x.json(meta)),scar==null?null:scar.defectKey(),scar==null?null:scar.severity(),scar==null?null:due,a.userId(),key,x.hash(input));var r=x.row(a,"SRM_QL_CASE",id,false);x.action(a,id,"CREATED",meta);x.notice(r,kind.equals("PPAP")?"供应商已建立PPAP草稿":"新的SCAR请质量联系人按期提交8D","case:"+id,true);x.audit(a,r,"QUALITY_CASE_CREATED");return detail(a,id);}
 public Map<String,Object> page(Context a,String kind,int current,int size){require(current>=1&&size>=1&&size<=100&&Set.of("PPAP","SCAR").contains(kind),400,"列表范围无效");var args=new ArrayList<Object>();String w=x.where(a,args,"c")+" AND c.KIND=?";args.add(kind);long total=x.db.queryForObject("SELECT COUNT(*) FROM SRM_QL_CASE c WHERE "+w,Long.class,args.toArray());args.add(size);args.add((current-1)*size);return Map.of("total",total,"records",x.db.queryForList("SELECT c.ID AS id,c.TITLE AS title,c.KIND AS kind,c.STATUS AS status,c.ROW_VERSION AS rowVersion,c.REVISION AS revision,c.DUE_MS AS dueAt,s.NAME AS supplierName FROM SRM_QL_CASE c JOIN SRM_SUPPLIER s ON s.ID=c.SUPPLIER_ID WHERE "+w+" ORDER BY c.CREATED_AT DESC,c.ID DESC LIMIT ? OFFSET ?",args.toArray()));}
 public Map<String,Object> detail(Context a,String id){var r=x.row(a,"SRM_QL_CASE",id,false);var out=new LinkedHashMap<String,Object>();for(String[] f:new String[][]{{"id","ID"},{"supplierId","SUPPLIER_ID"},{"kind","KIND"},{"title","TITLE"},{"status","STATUS"},{"rowVersion","ROW_VERSION"},{"revision","REVISION"},{"dueAt","DUE_MS"},{"severity","SEVERITY"},{"defectKey","DEFECT_KEY"},{"submittedBy","SUBMITTED_BY"}})out.put(f[0],r.get(f[1]));out.put("meta",x.object(x.crypto.decrypt(s(r,"META_CIPHER"))));out.put("payload",r.get("PAYLOAD_CIPHER")==null?Map.of():x.object(x.crypto.decrypt(s(r,"PAYLOAD_CIPHER"))));out.put("reviewComment",r.get("REVIEW_CIPHER")==null?"":x.crypto.decrypt(s(r,"REVIEW_CIPHER")));out.put("tasks",a.portal()||r.get("PROCESS_ID")==null?List.of():flow.tasks(s(r,"PROCESS_ID")));out.put("files",x.db.queryForList("SELECT ID AS id,FILE_NAME AS name,MIME AS mime,BYTE_SIZE AS size FROM SRM_QL_FILE WHERE CASE_ID=? ORDER BY CREATED_AT",id));out.put("revisions",x.db.queryForList("SELECT REVISION AS revision,STATUS AS status,CREATED_AT AS createdAt,CLOSED_AT AS closedAt FROM SRM_QL_REVISION WHERE CASE_ID=? ORDER BY REVISION",id));var actions=new ArrayList<Map<String,Object>>();for(var item:x.db.queryForList("SELECT * FROM SRM_QL_ACTION WHERE CASE_ID=? ORDER BY CREATED_AT,ID",id))actions.add(Map.of("action",item.get("ACTION"),"content",x.object(x.crypto.decrypt(s(item,"CONTENT_CIPHER"))),"createdAt",item.get("CREATED_AT")));out.put("history",actions);return out;}
 void files(String id,List<String> ids){require(!ids.isEmpty()&&new HashSet<>(ids).size()==ids.size(),400,"附件清单重复或为空");for(String f:ids)require(x.db.queryForObject("SELECT COUNT(*) FROM SRM_QL_FILE WHERE ID=? AND CASE_ID=?",Long.class,f,id)==1,404,"附件不属于本质量单据");}
 public Map<String,Object> submitPpap(Context a,String id,Ppap p){x.supplierWriter(a);var r=x.row(a,"SRM_QL_CASE",id,true);require(s(r,"KIND").equals("PPAP")&&Set.of("DRAFT","RETURNED").contains(s(r,"STATUS")),409,"PPAP当前不可提交");x.version(r,p.rowVersion());files(id,p.items().stream().map(Item::fileId).toList());return submit(a,r,p);}
 public Map<String,Object> reply(Context a,String id,EightD p){x.supplierWriter(a);var r=x.row(a,"SRM_QL_CASE",id,true);require(s(r,"KIND").equals("SCAR")&&Set.of("OPEN","RETURNED","ESCALATED").contains(s(r,"STATUS")),409,"SCAR当前不可回复");x.version(r,p.rowVersion());require(p.disciplines().keySet().equals(Set.of("D1","D2","D3","D4","D5","D6","D7","D8")),400,"须逐项完成D1至D8");files(id,p.fileIds());return submit(a,r,p);}
 Map<String,Object> submit(Context a,Map<String,Object> r,Object payload){String id=s(r,"ID"),pid=flow.start("srm_quality_review",id,Map.of("approvalId",id,"requestedBy",a.userId(),"businessType","QUALITY_REVIEW"));long rev=n(r,"REVISION")+1;String cipher=x.crypto.encrypt(x.json(payload));x.db.update("UPDATE SRM_QL_CASE SET STATUS='SUBMITTED',REVISION=?,ROW_VERSION=ROW_VERSION+1,PROCESS_ID=?,SUBMITTED_BY=?,REVIEWED_BY=NULL,REVIEW_CIPHER=NULL,PAYLOAD_CIPHER=?,UPDATED_AT=NOW(3) WHERE ID=?",rev,pid,a.userId(),cipher,id);x.db.update("INSERT INTO SRM_QL_REVISION(ID,CASE_ID,REVISION,PROCESS_ID,PAYLOAD_CIPHER,STATUS,SUBMITTED_BY,CREATED_AT) VALUES(?,?,?,?,?,'SUBMITTED',?,NOW(3))",id(),id,rev,pid,cipher,a.userId());x.action(a,id,"SUBMITTED",Map.of("revision",rev,"processId",pid));x.notice(r,"质量资料已提交，等待SQE审核",id+":submitted:"+rev,true);x.audit(a,r,"QUALITY_SUBMITTED");return detail(a,id);}
 public List<Map<String,Object>> tasks(Context a){x.sqe(a);var args=new ArrayList<Object>();String w=x.where(a,args,"c");var out=new ArrayList<Map<String,Object>>();for(var r:x.db.queryForList("SELECT c.* FROM SRM_QL_CASE c WHERE c.STATUS='SUBMITTED' AND "+w+" ORDER BY c.CREATED_AT LIMIT 1000",args.toArray()))if(!a.userId().equals(r.get("SUBMITTED_BY")))for(var t:flow.tasks(s(r,"PROCESS_ID")))if(s(t,"assignee").isBlank()||a.userId().equals(t.get("assignee"))){var item=new LinkedHashMap<String,Object>(t);item.put("caseId",r.get("ID"));item.put("kind",r.get("KIND"));item.put("title",r.get("TITLE"));out.add(item);}return out;}
 public Map<String,Object> review(Context a,String id,String task,Review p){x.sqe(a);var r=x.row(a,"SRM_QL_CASE",id,true);require(s(r,"STATUS").equals("SUBMITTED")&&!a.userId().equals(r.get("SUBMITTED_BY")),403,"无待审核资料或不能审核本人提交");require(flow.tasks(s(r,"PROCESS_ID")).stream().anyMatch(t->task.equals(t.get("id"))&&(s(t,"assignee").isBlank()||a.userId().equals(t.get("assignee")))),404,"任务不属于本单据或已转交他人");x.db.update("UPDATE SRM_QL_CASE SET REVIEWED_BY=?,REVIEW_CIPHER=? WHERE ID=?",a.userId(),x.crypto.encrypt(p.comment()),id);if(p.action().equals("APPROVE")){flow.complete(task,Map.of("decisionActor",a.userId()));require(flow.ended(s(r,"PROCESS_ID")),409,"仍有审核任务未完成");}else{flow.stop(s(r,"PROCESS_ID"),p.action());String state=p.action().equals("RETURN")||s(r,"KIND").equals("SCAR")?"RETURNED":"REJECTED";x.db.update("UPDATE SRM_QL_CASE SET STATUS=?,DUE_MS=CASE WHEN KIND='SCAR' THEN ? ELSE DUE_MS END,ROW_VERSION=ROW_VERSION+1,UPDATED_AT=NOW(3) WHERE ID=?",state,System.currentTimeMillis()+((Number)((Map<?,?>)x.object(x.crypto.decrypt(s(r,"META_CIPHER"))).get("policy")).get("responseDays")).longValue()*86400000,id);x.db.update("UPDATE SRM_QL_REVISION SET STATUS=?,REVIEWED_BY=?,REVIEW_CIPHER=?,CLOSED_AT=NOW(3) WHERE CASE_ID=? AND REVISION=?",state,a.userId(),x.crypto.encrypt(p.comment()),id,r.get("REVISION"));}x.action(a,id,"REVIEW_"+p.action(),Map.of("comment",p.comment(),"revision",r.get("REVISION")));x.notice(r,"SQE已返回质量审核意见",id+":review:"+r.get("REVISION"),true);x.audit(a,r,"QUALITY_REVIEWED");return detail(a,id);}
 @EventListener public void completed(SrmFlowCompleted e){var rows=x.db.queryForList("SELECT * FROM SRM_QL_CASE WHERE ID=?",e.approvalId());if(rows.isEmpty())return;var first=rows.get(0);var a=x.system(s(first,"ORG_ID"),e.actorId());var r=x.row(a,"SRM_QL_CASE",e.approvalId(),true);require(s(r,"STATUS").equals("SUBMITTED")&&e.processId().equals(r.get("PROCESS_ID"))&&e.actorId().equals(r.get("REVIEWED_BY"))&&!e.actorId().equals(r.get("SUBMITTED_BY")),409,"质量流程回写不匹配");String state=s(r,"KIND").equals("PPAP")?"APPROVED":"VERIFIED";x.db.update("UPDATE SRM_QL_CASE SET STATUS=?,ROW_VERSION=ROW_VERSION+1,UPDATED_AT=NOW(3) WHERE ID=?",state,r.get("ID"));x.db.update("UPDATE SRM_QL_REVISION SET STATUS=?,REVIEWED_BY=?,REVIEW_CIPHER=?,CLOSED_AT=NOW(3) WHERE CASE_ID=? AND REVISION=?",state,e.actorId(),r.get("REVIEW_CIPHER"),r.get("ID"),r.get("REVISION"));}
 public Map<String,Object> close(Context a,String id,Close p){x.sqe(a);var r=x.row(a,"SRM_QL_CASE",id,true);x.version(r,p.rowVersion());require(s(r,"KIND").equals("SCAR")&&s(r,"STATUS").equals("VERIFIED"),409,"8D验证通过后才能确认有效性并闭环");x.db.update("UPDATE SRM_QL_CASE SET STATUS='CLOSED',ROW_VERSION=ROW_VERSION+1,UPDATED_AT=NOW(3),CLOSED_AT=NOW(3) WHERE ID=?",id);x.action(a,id,"EFFECTIVENESS_CONFIRMED",Map.of("effectiveness",p.effectiveness(),"evidenceRef",p.evidenceRef()));x.notice(r,"8D有效性已确认，SCAR已闭环",id+":closed",true);x.audit(a,r,"SCAR_CLOSED");return detail(a,id);}
 public Map<String,Object> upload(Context a,String id,MultipartFile file){x.supplierWriter(a);var r=x.row(a,"SRM_QL_CASE",id,true);require(Set.of("DRAFT","OPEN","RETURNED","ESCALATED").contains(s(r,"STATUS")),409,"单据当前不能更改提交附件");try{byte[] b=file.getBytes();require(b.length>4&&b.length<=10485760,400,"附件须在10MB以内");String mime=new String(b,0,5,java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-")?"application/pdf":b.length>=8&&(b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71?"image/png":(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255?"image/jpeg":"";require(!mime.isBlank(),400,"仅支持PDF/PNG/JPEG附件");String fid=id(),engine=x.files.put(fid,b),name=Optional.ofNullable(file.getOriginalFilename()).orElse("quality").replaceAll("[\\\\/\\r\\n]","_");if(name.length()>128)name=name.substring(name.length()-128);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCompletion(int state){if(state!=STATUS_COMMITTED)x.files.delete(fid,engine);}});x.db.update("INSERT INTO SRM_QL_FILE VALUES(?,?,?,?,?,?,?,?,?,?,NOW(3))",fid,id,r.get("ORG_ID"),r.get("SUPPLIER_ID"),name,mime,cn.hutool.crypto.digest.DigestUtil.sha256Hex(b),b.length,engine,a.userId());return Map.of("id",fid,"name",name);}catch(java.io.IOException e){throw new vip.xiaonuo.common.exception.CommonException(400,"附件读取失败");}}
 public record FileData(byte[] bytes,String mime){}public FileData download(Context a,String fid){var rows=x.db.queryForList("SELECT * FROM SRM_QL_FILE WHERE ID=?",fid);require(rows.size()==1,404,"附件不存在");var f=rows.get(0);x.row(a,"SRM_QL_CASE",s(f,"CASE_ID"),false);byte[] b=x.files.read(fid,s(f,"STORAGE_ENGINE"));require(cn.hutool.crypto.digest.DigestUtil.sha256Hex(b).equals(f.get("CONTENT_SHA256")),409,"附件完整性检查失败");return new FileData(b,s(f,"MIME"));}
}
